 "content": "def transform(grid):
    """Project the solid color-2 rectangle's rows/columns to edges,
    but suppress a projection on any side containing a nonzero marker."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    for r, c in cells:
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            rr, cc = r + dr, c + dc
            ray = []
            while 0 <= rr < h and 0 <= cc < w:
                ray.append((rr, cc))
                rr += dr
                cc += dc
            # A marker (any nonzero color other than the 2-object) on
            # this outward ray blocks the entire extension in that direction.
            if any(grid[rr][cc] not in (0, 2) for rr, cc in ray):
                continue
            for rr, cc in ray:
                if grid[rr][cc] == 0:
                    out[rr][cc] = 2
    return out
