 "content": "def transform(grid):
    """Draw the grid-aligned projection of the 2-rectangle.

    Each exterior row/column reached by the rectangle's row/column band is
    filled with 2, except cells occupied by markers of other colors.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    # Rows of the rectangle continue horizontally to both edges.
    for r in range(r0, r1 + 1):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = 2
    # Columns of the rectangle continue vertically to both edges.
    for c in range(c0, c1 + 1):
        for r in range(h):
            if grid[r][c] == 0:
                out[r][c] = 2
    return out
