    """Extend each side of the color-2 rectangle to the grid edge.

    For every rectangle row/column, a marker anywhere along an outward
    side suppresses that whole side; otherwise fill that side with 2.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    for r in range(r0, r1 + 1):
        # Left side: marker anywhere between edge and rectangle blocks it.
        if not any(grid[r][c] not in (0, 2) for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] not in (0, 2) for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
